import { BUILTIN_ROLES, createInitialState, createRole, validateRole, exportRole, importRole, buildContextText, ROLE_LIMITS } from './shared.mjs';

const STORAGE = 'harness-studio-v1';
const $ = (s) => document.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
  layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
  chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-1 1v-9a8.5 8.5 0 1 1 18 0Z"/><path d="M7 10h10M7 14h6"/>',
  code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/>',
  book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2V4Z"/>',
  design:'<path d="m4 20 3-9L17 1l6 6L13 17l-9 3Zm3-9 6 6m2-14 6 6M4 20l5-2"/>',
  search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',
  pen:'<path d="m4 20 2-7L17 2l5 5-11 11-7 2Zm2-7 5 5m4-14 5 5M3 22h18"/>',
  heart:'<path d="M20.8 4.8a5.6 5.6 0 0 0-8 0l-.8.8-.8-.8a5.6 5.6 0 0 0-8 8L12 22l8.8-9.2a5.6 5.6 0 0 0 0-8Z"/><path d="M4 12h4l2-4 3 8 2-4h5"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',
  globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 1 1 4 2L12 12v2m0 3h.01"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
  spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  send:'<path d="m12 20 0-16m-6 6 6-6 6 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',
};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.layers}</svg>`;
const roleIcon=(r)=>`<div class="role-icon" style="--role-color:${/^#[a-f\d]{6}$/i.test(r.color)?r.color:'#E6E4FA'}">${icon(r.icon)}</div>`;
let storageHealthy=true;
let state=restore(), filter='All roles', query='', editorTab='context', runtime={available:false,authenticated:false,local:false}, running=null, pendingWorkspace=null, knowledgeTargetId=null;
state.memories ||= {};
const currentRole=()=>state.roles.find(r=>r.id===state.activeRoleId)||state.roles[0];
const currentSession=()=>state.sessions.find(s=>s.id===state.activeSessionId);
function restore(){
  try {const data=JSON.parse(localStorage.getItem(STORAGE)); if(!data||data.schemaVersion!==1) return createInitialState();
    if(!Array.isArray(data.roles)||!data.roles.length||data.roles.length>50) throw Error('roles');
    data.roles=data.roles.map(r=>importRole({schemaVersion:1,...r}));
    if(new Set(data.roles.map(r=>r.id)).size!==data.roles.length)throw Error('Duplicate role IDs');
    const sessionIds=new Set();
    data.sessions=(Array.isArray(data.sessions)?data.sessions:[]).filter(s=>{if(!validSession(s)||sessionIds.has(s.id))return false;sessionIds.add(s.id);return true;}).slice(0,100);
    data.memories=Object.fromEntries(Object.entries(data.memories||{}).filter(([k,v])=>data.roles.some(r=>r.id===k)&&typeof v==='string'&&new TextEncoder().encode(v).length<=ROLE_LIMITS.memory));
    if(!['workspace','library','editor','sessions','chat'].includes(data.view))data.view='workspace';return data;
  }catch{return createInitialState();}
}
function validSession(s){return Boolean(s&&typeof s.id==='string'&&/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i.test(s.id)&&typeof s.roleId==='string'&&Array.isArray(s.messages)&&s.messages.length<=100&&s.messages.every(m=>m&&['user','assistant'].includes(m.role)&&typeof m.content==='string'&&m.content.length<=100000)&&s.snapshot&&validateRole(s.snapshot).length===0&&s.roleId===s.snapshot.id&&typeof s.memory==='string'&&new TextEncoder().encode(s.memory).length<=ROLE_LIMITS.memory&&(s.title===undefined||(typeof s.title==='string'&&s.title.length<=100))&&(s.draft===undefined||(typeof s.draft==='string'&&new TextEncoder().encode(s.draft).length<=24000))&&typeof s.createdAt==='string'&&Number.isFinite(Date.parse(s.createdAt)));}
function parseWorkspace(data){
 if(!data||data.schemaVersion!==1||!Array.isArray(data.roles)||!data.roles.length||data.roles.length>50)throw Error('This is not a supported workspace file.');
 const roles=data.roles.map(r=>importRole({schemaVersion:1,...r}));
 if(new Set(roles.map(r=>r.id)).size!==roles.length)throw Error('Workspace role IDs must be unique.');
 const memories=Object.fromEntries(Object.entries(data.memories||{}).filter(([k,v])=>roles.some(r=>r.id===k)&&typeof v==='string'&&new TextEncoder().encode(v).length<=ROLE_LIMITS.memory));
 const sessions=data.sessions===undefined?[]:data.sessions;
 if(!Array.isArray(sessions)||sessions.length>100||!sessions.every(validSession)||new Set(sessions.map(s=>s.id)).size!==sessions.length)throw Error('The workspace contains invalid or duplicate sessions.');
 return {schemaVersion:1,roles,memories,sessions,activeRoleId:roles[0].id,view:'workspace'};
}
function confirmWorkspaceImport(next){
 pendingWorkspace=next;
 modal('Import this workspace?',`<p>This file contains ${next.roles.length} roles and ${next.sessions.length} sessions. Importing replaces the ${state.roles.length} roles and ${state.sessions.length} sessions currently saved in this browser.</p><div class="connect-note">Export your current workspace first if you want to keep both. No data changes until you choose “Replace workspace”. On another runtime, up to 24 recent messages (64 KB) are supplied to restore conversation context.</div>`,`<button class="button" data-action="export-workspace">Export current</button><button class="button" data-action="cancel-import">Cancel</button><button class="button primary" data-action="confirm-import">Replace workspace</button>`);
}
function applyWorkspaceImport(){
 if(!pendingWorkspace)return;
 if(running){toast('Stop the current response before replacing your workspace.');return;}
 const next=pendingWorkspace;
 try{localStorage.setItem(STORAGE,JSON.stringify(next));}catch{toast('Not enough browser storage. Your current workspace has been kept.');return;}
 state=next;pendingWorkspace=null;closeModal();render();toast('Workspace imported. Your roles are ready.');
}
function checkEditorDraft(){
 const invalid=$('#main [aria-invalid="true"]');
 if(!invalid)return true;
 invalid.focus();invalid.reportValidity();toast('Complete the highlighted field before using this context.');return false;
}
function boundedHistory(messages){
 const encoder=new TextEncoder(),decoder=new TextDecoder(),marker='\n[earlier content truncated]';
 const result=[];let total=0;
 for(const message of messages.slice(-24).reverse()){
  let content=message.content,encoded=encoder.encode(content);
  if(encoded.length>24000){content=decoder.decode(encoded.subarray(0,24000-encoder.encode(marker).length-3)).replace(/\ufffd$/,'')+marker;encoded=encoder.encode(content);}
  if(total+encoded.length>64000)break;
  result.unshift({role:message.role,content});total+=encoded.length;
 }
 return result;
}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageHealthy=true;const status=$('.save-status');if(status&&!$('#main [aria-invalid="true"]'))status.textContent='Saved in this browser';return true;}catch{storageHealthy=false;const status=$('.save-status');if(status)status.textContent='Storage full — export a copy';toast('Browser storage is full. Export your workspace to keep a copy.');return false;}}
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toasts').innerHTML=`<div class="toast">${esc(message)}</div>`;toastTimer=setTimeout(()=>$('#toasts').replaceChildren(),4200);}
function navigate(view){state.view=view;query='';filter='All roles';persist();render();window.scrollTo(0,0);}
function render(){
  const editor=['editor','chat'].includes(state.view), r=state.view==='chat'?currentSession()?.snapshot:currentRole();
  const title=state.view==='workspace'?'Your workspace':state.view==='library'?'Role library':state.view==='sessions'?'Your sessions':r?.name||'Workspace';
  $('#app').innerHTML=`<div class="mobile-overlay" data-action="close-menu"></div><aside class="sidebar">
    <button class="brand" data-action="nav" data-view="workspace" aria-label="Harness home"><img src="/favicon.svg" alt="">harness<span class="version">BETA</span></button>
    <div class="side-label">YOUR SPACE</div><nav class="nav" aria-label="Main navigation">
      <button class="${state.view==='workspace'||editor?'active':''}" data-action="nav" data-view="workspace">${icon('grid')}Workspace</button>
      <button class="${state.view==='library'?'active':''}" data-action="nav" data-view="library">${icon('layers')}Role library<span class="count">${state.roles.length}</span></button>
      <button class="${state.view==='sessions'?'active':''}" data-action="nav" data-view="sessions">${icon('chat')}Sessions${state.sessions.length?`<span class="count">${state.sessions.length}</span>`:''}</button></nav>
    <div class="sidebar-spacer"></div><div class="sidebar-note">${icon('spark')}A place for every kind of thinking.</div>
    <div class="runtime-card"><div class="runtime-top"><span class="claude-mark" aria-hidden="true">✳</span>Claude Code<span class="status-dot ${runtime.authenticated?'connected':''}"></span></div><p>${runtime.authenticated?'Connected on this computer':'Bring your own subscription'}</p><button data-action="connect">${runtime.authenticated?'Runtime settings':'Connect runtime'} ${icon('arrow')}</button></div>
    <div class="side-bottom"><button data-action="help">${icon('help')}A little guidance<span class="shortcut">?</span></button><button data-action="export-workspace">${icon('download')}Export workspace</button></div>
  </aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-action="open-menu" aria-label="Open menu">${icon('menu')}</button>${icon('grid')}${icon('chevron')}<strong>${esc(title)}</strong></div><div class="topbar-right"><span class="save-status">${icon('check')}${storageHealthy?'Saved in this browser':'Storage full — export a copy'}</span><div class="avatar" aria-label="Personal workspace">You</div></div></header><main class="content" id="main">${state.view==='editor'?renderEditor():state.view==='chat'?renderChat():state.view==='sessions'?renderSessions():renderDashboard()}</main></div>`;
  bindInputs();
}
function renderDashboard(){
  const library=state.view==='library';
  return `<section class="page-heading"><div><div class="eyebrow">${library?'A ROLE FOR EVERY IDEA':'YOUR PERSONAL AI WORKSPACE'}</div><h1>${library?'Find your next thinking partner.':'Your AI. In its element.'}</h1><p>${library?'Start with a thoughtful foundation. Shape it around your work.':'Give your AI the context to do its best work. Make it yours.'}</p></div><button class="button primary" data-action="create">${icon('plus')}Create a role</button></section>
    ${!library?`<section class="hero"><div><div class="eyebrow">SAME INTELLIGENCE. NEW POSSIBILITIES.</div><h2>The right context<br>changes everything.</h2><p>A teacher for your curiosity. An engineer for your ideas.<br>A workspace for whatever comes next.</p><button class="hero-link" data-action="nav" data-view="library">Explore the role library ${icon('arrow')}</button></div><div class="orbit" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-ring two"></div><div class="orbit-ring three"></div><div class="orbit-core"><img src="/favicon.svg" alt=""></div><span class="orbit-tag">${icon('book')}Teacher</span><span class="orbit-tag second">${icon('code')}Engineer</span><span class="orbit-tag third">${icon('design')}Designer</span><span class="spark">✧</span><span class="spark two">✦</span></div></section>`:''}
    <section aria-label="Your roles"><div class="section-title"><h2>${library?'Role library':'Your roles'}<span class="number-badge">${state.roles.length}</span></h2><button class="text-button" data-action="import">${icon('upload')}Import a role</button></div><div class="toolbar"><div class="filters" role="group" aria-label="Filter roles">${['All roles','Recently used','Custom roles'].map(f=>`<button class="filter ${filter===f?'active':''}" data-action="filter" data-filter="${f}">${f}</button>`).join('')}</div><label class="search">${icon('search')}<input id="role-search" type="search" placeholder="Find a role…" aria-label="Find a role" value="${esc(query)}"></label></div><div class="role-grid" id="role-grid">${renderCards()}</div></section><div class="bottom-strip">${icon('shield')}Your roles and notes stay in this browser. You choose what to share.</div><footer class="footer-copy"><span>A little structure for a lot of possibility.</span><button data-action="help">Made for your way of working ${icon('arrow')}</button></footer>`;
}
function renderCards(){
  let roles=state.roles.filter(r=>`${r.name} ${r.description} ${r.category}`.toLowerCase().includes(query.toLowerCase()));
  if(filter==='Custom roles')roles=roles.filter(r=>!BUILTIN_ROLES.some(b=>b.id===r.id));
  if(filter==='Recently used')roles=roles.filter(r=>state.sessions.some(s=>s.roleId===r.id));
  return roles.length?roles.map(r=>`<article class="role-card"><div class="card-top">${roleIcon(r)}<span class="starter">${BUILTIN_ROLES.some(b=>b.id===r.id)?'STARTER ROLE':'YOUR CREATION'}</span></div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="card-foot"><span>${icon('layers')}${r.workflow.length}-step workflow${r.knowledge.length?` · ${r.knowledge.length} sources`:''}</span><button class="card-open" data-action="open-role" data-id="${esc(r.id)}">Make it yours ${icon('arrow')}</button></div></article>`).join(''):`<div class="search-result-empty">${query?'No roles match your search. Try another word.':filter==='Recently used'?'Your recently used roles will appear here after you start a session.':'Your own creations belong here. Create your first role to get started.'}</div>`;
}
function renderEditor(){
 const r=currentRole(); if(!r)return '';
 return `<button class="back-link" data-action="nav" data-view="workspace">${icon('back')}Back to your workspace</button><section class="page-heading"><div class="role-heading">${roleIcon(r)}<div><h1>${esc(r.name)}</h1><p>${esc(r.subtitle)}</p></div></div><div class="heading-actions"><button class="button" data-action="export-role">${icon('download')}Export role</button><button class="button primary" data-action="start-session">${icon('chat')}Start session</button></div></section><div class="tabs" role="tablist" aria-label="Role configuration">${[['context','Context'],['knowledge','Knowledge'],['memory','Memory']].map(([v,n])=>`<button role="tab" aria-selected="${editorTab===v}" class="${editorTab===v?'active':''}" data-action="tab" data-tab="${v}">${n}${v==='knowledge'?` <span class="number-badge">${r.knowledge.length}</span>`:''}</button>`).join('')}</div><div class="editor-grid"><div>${editorTab==='knowledge'?renderKnowledge(r):editorTab==='memory'?renderMemory(r):renderContextEditor(r)}</div><aside class="editor-aside"><section class="panel"><div class="mini-label">THE CONTEXT YOU'RE CREATING</div><h2>A little structure. A clearer direction.</h2><p class="help">Your instructions shape the conversation. Your references give it something to work with.</p><div class="context-metric"><span>Role</span><strong>${esc(r.name)}</strong></div><div class="context-metric"><span>Language</span><strong id="metric-language">${esc(r.language)}</strong></div><div class="context-metric"><span>Workflow</span><strong>${r.workflow.length} steps</strong></div><div class="context-metric"><span>Knowledge</span><strong>${r.knowledge.length} document${r.knowledge.length===1?'':'s'}</strong></div><div class="context-metric"><span>Tools</span><strong>Conversation + supplied text</strong></div><div class="context-preview" id="context-summary">${esc(r.instructions.slice(0,290))}…</div><button class="button small" data-action="preview-context">${icon('layers')}Inspect full context</button></section><section class="panel"><div class="mini-label">A GOOD PLACE TO START</div><h2>Bring a question.</h2><p class="help">Try one of these, or start with your own idea.</p>${r.starterPrompts.map((p,i)=>`<button class="starter-prompt" data-action="starter" data-index="${i}">${esc(p)}${icon('arrow')}</button>`).join('')}</section></aside></div>`;
}
function renderContextEditor(r){return `<section class="panel"><h2>Set the scene</h2><p class="help">Tell your AI who it's helping, what matters, and how to work with you.</p><div class="field"><label for="role-name">Role name</label><input id="role-name" value="${esc(r.name)}" maxlength="100"></div><div class="field"><label for="role-description">A short introduction</label><textarea id="role-description" maxlength="1000" style="min-height:75px">${esc(r.description)}</textarea></div><div class="field"><label for="role-instructions" class="label-row">Instructions <span class="char-count" id="instruction-count">${r.instructions.length.toLocaleString()} characters</span></label><textarea id="role-instructions" class="instructions" maxlength="24000" spellcheck="false">${esc(r.instructions)}</textarea><small>Be specific about the outcome, approach, and limits. Changes save automatically.</small></div><div class="field"><label for="role-language">Conversation language</label><select id="role-language">${[...new Set(['English','Hinglish','Hindi','Match my language',r.language])].map(l=>`<option ${r.language===l?'selected':''}>${esc(l)}</option>`).join('')}</select></div></section><section class="panel"><div class="label-row"><h2>A way of working</h2><button class="text-button" data-action="add-step">${icon('plus')}Add step</button></div><p class="help">A flexible guide for getting from a question to a useful result.</p>${r.workflow.map((s,i)=>`<div class="workflow-step"><span class="step-number">${i+1}</span><input data-workflow="${i}" aria-label="Workflow step ${i+1}" value="${esc(s)}" maxlength="300"><button class="icon-button" data-action="remove-step" data-index="${i}" aria-label="Remove workflow step ${i+1}">${icon('close')}</button></div>`).join('')}</section><div class="save-actions"><button class="button ghost danger" data-action="delete-role">${icon('trash')}Remove role</button></div>`;}
function renderKnowledge(r){return `<section class="panel"><h2>Give it something to go on</h2><p class="help">Add notes, project briefs, syllabuses, or reference text. These are included when you start a new session.</p><div class="upload-area" id="drop-zone">${icon('upload')}<h3>Drop your references here</h3><p>Text, Markdown, CSV, JSON, and code files<br>40 KB per file · 120 KB total · 20 files</p><button class="button small" data-action="upload-knowledge">Choose files</button></div>${r.knowledge.map(d=>`<div class="file-row">${icon('file')}<div class="file-meta"><strong>${esc(d.name)}</strong><small>${(d.size/1000).toFixed(1)} KB · available to this role</small></div><button class="icon-button" data-action="view-document" data-id="${esc(d.id)}" aria-label="Read ${esc(d.name)}">${icon('search')}</button><button class="icon-button" data-action="remove-document" data-id="${esc(d.id)}" aria-label="Remove ${esc(d.name)}">${icon('trash')}</button></div>`).join('')}<p class="inline-help">Only add material you're comfortable sending to Claude. References are context, not verified facts. PDF import is a later addition.</p></section><section class="panel"><h2>Or add a quick note</h2><p class="help">Keep useful background within reach.</p><form id="note-form"><div class="field"><label for="note-name">Title</label><input id="note-name" name="name" placeholder="e.g. My project brief" required maxlength="100"></div><div class="field"><label for="note-content">Reference text</label><textarea id="note-content" name="content" placeholder="Paste the details your role should know…" required maxlength="40000"></textarea></div><button class="button primary small" type="submit">${icon('plus')}Add to knowledge</button></form></section>`;}
function renderMemory(r){return `<section class="panel"><div class="toggle-row"><div><h2>A little continuity</h2><p>Include your saved notes when you start a session.</p></div><button role="switch" aria-checked="${r.memoryEnabled}" aria-label="Include saved notes" class="toggle ${r.memoryEnabled?'on':''}" data-action="toggle-memory"></button></div><div class="field" style="margin-top:24px"><label for="memory-notes">What should this role remember?</label><textarea id="memory-notes" class="memory-input" maxlength="20000" placeholder="Your goals, preferences, current project, or what you'd like to pick up next…">${esc(state.memories[r.id]||'')}</textarea><small>Saved for this role only. You can edit or clear these notes at any time.</small></div><div class="memory-notice">These notes are maintained by you. Conversations keep their own context snapshot, so updates apply to new sessions. Automatic memory extraction isn't enabled.</div></section>`;}
function renderSessions(){return `<section class="page-heading"><div><div class="eyebrow">PICK UP THE THREAD</div><h1>Your conversations, in context.</h1><p>A separate space for each role, idea, and train of thought.</p></div><button class="button primary" data-action="nav" data-view="workspace">${icon('plus')}New session</button></section>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<article class="session-row">${roleIcon(s.snapshot)}<div><h3>${esc(s.title||`A new conversation with ${s.snapshot.name}`)}</h3><small>${esc(s.snapshot.name)} · ${s.messages.filter(m=>m.role==='user').length} messages · ${formatDate(s.updatedAt||s.createdAt)}</small></div><div class="session-actions"><button class="button small" data-action="open-session" data-id="${esc(s.id)}">Open ${icon('arrow')}</button><button class="icon-button" data-action="delete-session" data-id="${esc(s.id)}" aria-label="Delete session">${icon('trash')}</button></div></article>`).join(''):`<div class="empty-state"><div class="empty-icon">${icon('chat')}</div><h2>Good things start with a question.</h2><p>Choose a role and start your first conversation. Your sessions will stay here so you can come back to them.</p><button class="button primary" data-action="nav" data-view="workspace">Find your role ${icon('arrow')}</button></div>`}`;}
function renderChat(){const s=currentSession();if(!s){state.view='sessions';return renderSessions();}const r=s.snapshot,isRunning=running?.id===s.id;return `<button class="back-link" data-action="nav" data-view="sessions">${icon('back')}All sessions</button><section class="page-heading"><div class="role-heading">${roleIcon(r)}<div><h1>${esc(r.name)}</h1><p>${esc(r.subtitle)}</p></div></div><button class="button small" data-action="chat-context">${icon('layers')}Session context</button></section><div class="chat-layout"><div class="chat-info"><span class="workspace-count"><span class="status-dot ${runtime.authenticated?'connected':''}"></span>${runtime.authenticated?'Claude Code connected':'Runtime not connected'}</span><span>${r.knowledge.length} sources · ${esc(r.language)} · Context snapshot</span></div><div class="chat-messages" id="messages">${s.messages.length?s.messages.map((m,i)=>renderMessage(m,i,s)).join(''):`<div class="chat-intro">${roleIcon(r)}<h2>${esc(r.subtitle)}</h2><p>${runtime.authenticated?'Your role is ready. Bring a question, an idea, or something you want to figure out.':'Your context is ready. Connect your local Claude runtime to turn it into a conversation.'}</p>${r.starterPrompts.map((p,i)=>`<button class="starter-prompt" data-action="chat-starter" data-index="${i}">${esc(p)}${icon('arrow')}</button>`).join('')}</div>`}</div><div id="chat-error"></div><form class="composer" id="chat-form"><textarea id="chat-prompt" aria-label="Message your role" placeholder="${esc(`Ask your ${r.name.toLowerCase()} anything…`)}" maxlength="24000" ${isRunning?'disabled':''}>${esc(s.draft||'')}</textarea><div class="composer-foot"><span>${icon('shield')}Your context. Your Claude account.</span>${isRunning?`<button type="button" class="button small" data-action="stop">${icon('stop')}Stop</button>`:`<button class="button primary small" type="submit">${runtime.authenticated?`Send ${icon('send')}`:`Connect to chat ${icon('arrow')}`}</button>`}</div></form><div class="composer-note">${runtime.authenticated?'Replies use your Claude account and its usage limits.':'No model is running on this hosted workspace. Your draft stays here.'}</div></div>`;}
function renderMessage(m,i,s){return `<div class="message ${m.role}"><div class="message-avatar">${m.role==='user'?'You':icon(s.snapshot.icon)}</div><div class="message-body" ${m.role==='assistant'&&i===s.messages.length-1?'id="stream-body"':''}><strong>${m.role==='user'?'You':esc(s.snapshot.name)}</strong><span>${esc(m.content)||'<span class="loading-dots">Thinking…</span>'}</span></div></div>`;}
function formatDate(v){try{return new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric'});}catch{return 'Recently';}}
function bindInputs(){
 const search=$('#role-search');if(search)search.addEventListener('input',e=>{query=e.target.value;$('#role-grid').innerHTML=renderCards();});
 for(const [selector,key]of[['#role-name','name'],['#role-description','description'],['#role-instructions','instructions'],['#role-language','language']]){$(selector)?.addEventListener('input',e=>{const r=currentRole(),old=r[key];r[key]=e.target.value;const errors=validateRole(r);if(errors.length){r[key]=old;e.target.setCustomValidity(errors[0]);e.target.setAttribute('aria-invalid','true');const saved=$('.save-status');if(saved)saved.textContent='Unsaved field — check your context';return;}e.target.setCustomValidity('');e.target.removeAttribute('aria-invalid');persist();if(key==='instructions'){$('#instruction-count').textContent=`${r.instructions.length.toLocaleString()} characters`;$('#context-summary').textContent=`${r.instructions.slice(0,290)}…`;}if(key==='language')$('#metric-language').textContent=r.language;});}
 document.querySelectorAll('[data-workflow]').forEach(el=>el.addEventListener('input',e=>{if(!e.target.value.trim()){e.target.setCustomValidity('A workflow step cannot be empty.');e.target.setAttribute('aria-invalid','true');return;}e.target.setCustomValidity('');e.target.removeAttribute('aria-invalid');currentRole().workflow[Number(el.dataset.workflow)]=e.target.value;persist();}));
 $('#memory-notes')?.addEventListener('input',e=>{if(new TextEncoder().encode(e.target.value).length>ROLE_LIMITS.memory){e.target.setCustomValidity('Keep these notes below 20 KB.');e.target.setAttribute('aria-invalid','true');return;}e.target.setCustomValidity('');e.target.removeAttribute('aria-invalid');state.memories[currentRole().id]=e.target.value;persist();});
 $('#note-form')?.addEventListener('submit',e=>{e.preventDefault();addDocuments([{id:crypto.randomUUID(),name:$('#note-name').value.trim(),content:$('#note-content').value,size:new TextEncoder().encode($('#note-content').value).length}]);});
 $('#chat-prompt')?.addEventListener('input',e=>{currentSession().draft=e.target.value;persist();});
 $('#chat-prompt')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit();}});
 $('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();sendChat();});
 const drop=$('#drop-zone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.style.background='#f0e9fc';});drop.addEventListener('dragleave',()=>drop.style.background='');drop.addEventListener('drop',e=>{e.preventDefault();readKnowledge(e.dataTransfer.files,currentRole().id);});}
}
function openRole(id){if(!state.roles.some(r=>r.id===id))return;state.activeRoleId=id;editorTab='context';navigate('editor');}
function startSession(prompt=''){if(!checkEditorDraft())return;const r=currentRole();if(validateRole(r).length){toast('Complete the role instructions before starting.');return;}if(state.sessions.length>=100){toast('You have 100 sessions. Export or remove an older session first.');return;}const s={id:crypto.randomUUID(),roleId:r.id,snapshot:structuredClone(r),memory:r.memoryEnabled?(state.memories[r.id]||''):'',messages:[],draft:prompt,createdAt:new Date().toISOString()};state.sessions.push(s);state.activeSessionId=s.id;navigate('chat');$('#chat-prompt')?.focus();}
function modal(title,body,footer=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!d.open)d.showModal();document.body.classList.add('modal-open');}
function closeModal(){pendingWorkspace=null;$('#modal').close();document.body.classList.remove('modal-open');}
$('#modal').addEventListener('close',()=>document.body.classList.remove('modal-open'));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
function connectModal(){modal(runtime.authenticated?'Your runtime is connected':'Bring your Claude subscription',runtime.authenticated?`<p>Claude Code ${esc(runtime.version)} is running on this computer. Your conversations use its existing account.</p><div class="connect-note">${esc(runtime.detail)} This version supports conversation and your supplied documents. External tools are disabled.</div>`:runtime.local?`<p>${esc(runtime.detail||'Checking your local Claude installation…')}</p><div class="connect-step"><div><h3>Sign in through Claude Code</h3><p>In your terminal, run:</p><div class="code-block">claude auth login</div></div></div><p>Then choose “Check connection” below. Your credentials stay with Claude Code.</p>`:`<p>Your subscription runs on your computer. The local version of Harness connects to your official Claude Code installation.</p><div class="connect-steps"><div class="connect-step"><div><h3>Download the local workspace</h3><p>Requires Node.js 22+ and the official Claude Code CLI.</p><a class="button small" style="margin-top:10px" href="/downloads/harness-studio.zip" download>${icon('download')}Download Harness</a></div></div><div class="connect-step"><div><h3>Unzip, then start it</h3><div class="code-block">cd harness-studio
npm start</div></div></div><div class="connect-step"><div><h3>Open your local workspace</h3><p>Visit <a href="http://127.0.0.1:4317" target="_blank" rel="noopener">127.0.0.1:4317</a>. If needed, sign in with <code>claude auth login</code>.</p></div></div></div><div class="connect-note">Taking your roles with you? Export this workspace, then import it in the local version. The hosted version stores your drafts in this browser and doesn't make model calls.</div>`,`${runtime.local?'<button class="button primary" data-action="reconnect">Check connection</button>':'<button class="button" data-action="export-workspace">Export workspace</button>'}<button class="button ${runtime.local?'':'primary'}" data-action="close-modal">${runtime.authenticated?'Done':'Got it'}</button>`);}
function createModal(){modal('Make room for a new role',`<p>Start with a foundation, then give it a perspective of its own.</p><form id="create-form"><div class="field"><label for="new-name">What will you call it?</label><input id="new-name" name="name" placeholder="e.g. My physics tutor" required maxlength="100"></div><div class="field"><label for="new-description">What should it help you with?</label><textarea id="new-description" name="description" placeholder="Explain class 11 physics in Hinglish, with examples and practice questions." required maxlength="1000"></textarea></div><div class="field"><label for="new-template">Start from</label><select id="new-template"><option value="blank">A blank canvas</option>${BUILTIN_ROLES.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div><p class="inline-help">This creates an editable role template. You can refine its instructions, workflow, and knowledge next.</p><div class="form-error" id="create-error" role="alert"></div></form>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit" form="create-form">${icon('plus')}Create role</button>`);$('#create-form').addEventListener('submit',e=>{e.preventDefault();try{if(state.roles.length>=50)throw Error('This workspace supports up to 50 roles.');const base=BUILTIN_ROLES.find(r=>r.id===$('#new-template').value);const description=$('#new-description').value.trim();const r=createRole({...base,name:$('#new-name').value.trim(),description,knowledge:[],...(base?{instructions:`User's specific goal: ${description}\n\n${base.instructions}`}:{})});state.roles.push(r);closeModal();openRole(r.id);toast('Your role is ready to make your own.');}catch(err){$('#create-error').textContent=err.message;}});$('#new-name').focus();}
function download(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportWorkspace(){download('harness-workspace.json',{schemaVersion:1,roles:state.roles,memories:state.memories,sessions:state.sessions});toast('Workspace exported. Keep this file somewhere you trust.');}
function inspectContext(r,memory=''){modal('The context behind the conversation',`<p>A readable view of the role, workflow, references, and saved notes. Reference content is marked as untrusted data.</p><pre>${esc(buildContextText(r,memory))}</pre>`,`<button class="button" data-action="close-modal">Done</button>`);}
async function readKnowledge(files,targetId=currentRole()?.id){try{const docs=[];for(const f of Array.from(files)){if(f.size>ROLE_LIMITS.knowledgeFileBytes)throw Error(`${f.name} is larger than 40 KB.`);if(!/\.(txt|md|csv|json|html|css|js|ts|py)$/i.test(f.name))throw Error('Choose a text, Markdown, CSV, JSON, or code file.');const content=await f.text();if(content.includes('\u0000'))throw Error('Binary files are not supported.');docs.push({id:crypto.randomUUID(),name:f.name,content,size:new TextEncoder().encode(content).length});}addDocuments(docs,targetId);}catch(e){toast(e.message);}finally{$('#knowledge-file').value='';}}
function addDocuments(docs,targetId=currentRole()?.id){const r=state.roles.find(r=>r.id===targetId);if(!r){toast('That role is no longer available. No references were added.');return;}if(!docs.length)return;const next={...r,knowledge:[...r.knowledge,...docs]};const errors=validateRole(next);if(errors.length){toast(errors[0]);return;}r.knowledge=next.knowledge;persist();render();toast(`${docs.length===1?'Reference':'References'} added to ${r.name}.`);}
async function probe(){runtime.local=['127.0.0.1','localhost','[::1]'].includes(location.hostname);if(!runtime.local)return;try{const res=await fetch('/api/status',{signal:AbortSignal.timeout(15000),cache:'no-store'});if(!res.ok)throw Error('Runtime is not available at this address.');const info=await res.json();runtime={...info,local:true};}catch(e){runtime={available:false,authenticated:false,local:true,detail:e.message};}render();}
async function sendChat(){
 const s=currentSession();if(!s)return;if(running){toast('Another response is in progress. Open that session to stop it, or wait for it to finish.');return;}const prompt=$('#chat-prompt').value.trim();if(!runtime.authenticated){connectModal();return;}if(!prompt){toast('Start with a question or an idea.');return;}if(new TextEncoder().encode(prompt).length>24000){toast('Keep your message below 24 KB.');return;}if(s.messages.length>=98){toast('Start a new session to continue with a fresh context.');return;}
 s.messages.push({role:'user',content:prompt},{role:'assistant',content:''});s.title ||= prompt.slice(0,75);s.draft='';s.updatedAt=new Date().toISOString();const controller=new AbortController();running={controller,id:s.id};persist();render();
 const reply=s.messages.at(-1);let completed=false;
 try{const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Harness-Request':'local'},signal:controller.signal,body:JSON.stringify({sessionId:s.id,role:{id:s.snapshot.id,name:s.snapshot.name,instructions:s.snapshot.instructions,language:s.snapshot.language,workflow:s.snapshot.workflow},knowledge:s.snapshot.knowledge.map(({name,content})=>({name,content})),memory:s.memory,history:boundedHistory(s.messages.slice(0,-2)),prompt})});
 if(!res.ok){const err=await res.json().catch(()=>({error:'The runtime could not start this conversation.'}));throw Error(err.error||err.message||'The runtime could not start this conversation.');}
 const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';
 function event(line){if(!line.trim())return;const ev=JSON.parse(line);if(ev.type==='text'&&typeof ev.text==='string'){reply.content+=ev.text;if(reply.content.length>100000)throw Error('The reply reached this workspace’s size limit.');const body=$('#stream-body span');if(state.activeSessionId===s.id&&body){body.textContent=reply.content;body.scrollIntoView({block:'nearest'});}}if(ev.type==='done')completed=true;if(ev.type==='error')throw Error(ev.message);}
 while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines)event(line);}buffer+=decoder.decode();if(buffer.trim())event(buffer);if(!completed)throw Error('The connection ended before the response completed.');
 }catch(e){s.lastError=e.name==='AbortError'?'Response stopped.':e.message;controller.abort();if(!reply.content){s.messages.splice(-2,2);s.draft=prompt;}toast(s.lastError);}
 finally{running=null;s.updatedAt=new Date().toISOString();persist();if(state.view==='chat'&&state.activeSessionId===s.id){render();if(s.lastError){$('#chat-error').innerHTML=`<div class="error-notice" role="alert">${esc(s.lastError)}</div>`;delete s.lastError;persist();}}}
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='nav'){navigate(b.dataset.view);return;}if(a==='close-modal'){closeModal();return;}if(a==='open-menu'){$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('open');return;}if(a==='close-menu'){$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('open');return;}
 if(a==='confirm-import'){applyWorkspaceImport();return;}if(a==='cancel-import'){closeModal();return;}if(a==='create'){createModal();return;}if(a==='connect'){connectModal();return;}if(a==='reconnect'){closeModal();await probe();connectModal();return;}
 if(a==='filter'){filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));$('#role-grid').innerHTML=renderCards();return;}
 if(a==='open-role'){openRole(b.dataset.id);return;}if(a==='tab'){editorTab=b.dataset.tab;render();return;}if(a==='start-session'){startSession();return;}if(a==='starter'){startSession(currentRole().starterPrompts[Number(b.dataset.index)]);return;}
 if(a==='chat-starter'){const s=currentSession();s.draft=s.snapshot.starterPrompts[Number(b.dataset.index)];persist();$('#chat-prompt').value=s.draft;$('#chat-prompt').focus();return;}
 if(a==='preview-context'){const r=currentRole();inspectContext(r,r.memoryEnabled?state.memories[r.id]||'':'');return;}if(a==='chat-context'){const s=currentSession();inspectContext(s.snapshot,s.memory);return;}
 if(a==='export-role'){if(!checkEditorDraft())return;const r=currentRole();download(`${r.id}-role.json`,exportRole(r));toast('Role exported. Import it in another Harness workspace.');return;}if(a==='export-workspace'){exportWorkspace();return;}
 if(a==='import'){$('#import-file').click();return;}if(a==='import-workspace'){closeModal();$('#import-file').click();return;}
 if(a==='add-step'){const r=currentRole();if(r.workflow.length>=8){toast('A role can have up to 8 workflow steps.');return;}r.workflow.push('Review the next step');persist();render();return;}
 if(a==='remove-step'){const r=currentRole();if(r.workflow.length===1){toast('Keep at least one workflow step.');return;}r.workflow.splice(Number(b.dataset.index),1);persist();render();return;}
 if(a==='toggle-memory'){currentRole().memoryEnabled=!currentRole().memoryEnabled;persist();render();return;}
 if(a==='upload-knowledge'){knowledgeTargetId=currentRole().id;$('#knowledge-file').click();return;}if(a==='remove-document'){const r=currentRole();r.knowledge=r.knowledge.filter(d=>d.id!==b.dataset.id);persist();render();toast('Reference removed from future sessions.');return;}
 if(a==='view-document'){const d=currentRole().knowledge.find(d=>d.id===b.dataset.id);if(d)modal(d.name,`<pre>${esc(d.content)}</pre>`,`<button class="button" data-action="close-modal">Done</button>`);return;}
 if(a==='open-session'){state.activeSessionId=b.dataset.id;navigate('chat');return;}if(a==='stop'){running?.controller.abort();return;}
 if(a==='delete-session'){const id=b.dataset.id;modal('Remove this session?',`<p>This removes the conversation from this browser. Native Claude history on your computer is managed separately.</p>`,`<button class="button" data-action="close-modal">Keep session</button><button class="button primary" data-action="confirm-delete-session" data-id="${esc(id)}">Remove session</button>`);return;}
 if(a==='confirm-delete-session'){if(running?.id===b.dataset.id){toast('Stop this response before removing the session.');return;}state.sessions=state.sessions.filter(s=>s.id!==b.dataset.id);closeModal();persist();render();toast('Session removed from this browser.');return;}
 if(a==='delete-role'){modal('Remove this role?',`<p>Your existing sessions keep their context. Export this role first if you'd like to use it again.</p>`,`<button class="button" data-action="close-modal">Keep role</button><button class="button primary" data-action="confirm-delete-role">Remove role</button>`);return;}
 if(a==='confirm-delete-role'){if(state.roles.length===1){toast('Keep at least one role in your workspace.');return;}const r=currentRole();state.roles=state.roles.filter(x=>x.id!==r.id);delete state.memories[r.id];state.activeRoleId=state.roles[0].id;closeModal();navigate('workspace');return;}
 if(a==='help'){modal('A workspace shaped around you',`<p>Choose a role, give it a little context, and start with a question.</p><div class="connect-step"><div><h3>Make a role your own</h3><p>Edit its instructions, choose a language, and add a workflow. Changes save in this browser.</p></div></div><div class="connect-step"><div><h3>Bring what matters</h3><p>Add reference text and your own memory notes. New sessions receive a snapshot of that context.</p></div></div><div class="connect-step"><div><h3>Connect when you're ready</h3><p>Run the local version to use your own Claude Code account. Hosted role editing and exports work without a model.</p></div></div><div class="connect-note">Browser data stays on this device. Export a backup before clearing browser storage. The local runtime sends the context and messages you choose to submit to your Claude account.</div>`,`<button class="button" data-action="import-workspace">${icon('upload')}Import workspace</button><button class="button primary" data-action="close-modal">Got it</button>`);return;}
});
$('#knowledge-file').addEventListener('change',e=>{readKnowledge(e.target.files,knowledgeTargetId||currentRole()?.id);knowledgeTargetId=null;});
$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>4_000_000)throw Error('Choose a JSON file smaller than 4 MB.');const data=JSON.parse(await f.text());if(Array.isArray(data.roles)){confirmWorkspaceImport(parseWorkspace(data));}else{if(state.roles.length>=50)throw Error('This workspace supports up to 50 roles.');const r=importRole(data);if(state.roles.some(x=>x.id===r.id)){r.id=`custom-${crypto.randomUUID()}`;r.name=`${r.name.slice(0,90)} (copy)`;}state.roles.push(r);openRole(r.id);toast('Role imported. Make yourself at home.');}}catch(err){toast(`Couldn't import: ${err.message}`);}finally{e.target.value='';}});
render();probe();
